piezas.css:
.bb-acceso{background:#000;color:#fff;font-family:"Chivo",system-ui,sans-serif;padding:48px 32px;max-width:520px}
.bb-acceso h1{margin:0 0 24px;font-size:2rem;font-weight:700}
.bb-acceso__form{display:flex;flex-direction:column;gap:16px;max-width:420px}
.bb-acceso__form label{display:flex;flex-direction:column;gap:.35em;font-size:.85rem;color:#999}
.bb-acceso__form input{font-family:inherit;font-size:.95rem;color:#fff;background:#111;border:1px solid #2b2b2b;border-radius:4px;padding:.6em .75em}
.bb-acceso__btn{align-self:flex-start;display:inline-flex;align-items:center;justify-content:center;padding:.85em 1.6em;border-radius:999px;background:#facbe5;color:#1a1a1a;font:700 .95rem "Chivo",system-ui,sans-serif;border:0;cursor:pointer;transition:background-color .2s,transform .2s,box-shadow .2s}
.bb-acceso__btn:hover{background:#f9e4ed;transform:translateY(-1px);box-shadow:0 6px 16px -6px rgba(245,156,197,.5)}
.bb-acceso__btn:active{transform:scale(.97)}
.bb-acceso__error{color:#950f1e;font-size:.85rem;margin:0}

.bb-tabs{display:flex;gap:16px;margin:32px 0;border-bottom:1px solid #2b2b2b;background:#000;padding:0 16px;font-family:"Chivo",system-ui,sans-serif}
.bb-tabs__btn{background:none;border:none;color:#999;font:700 1rem "Chivo",system-ui,sans-serif;padding:.6em .2em;margin-bottom:-1px;border-bottom:2px solid transparent;cursor:pointer}
.bb-tabs__btn.is-active{color:#fff;border-bottom-color:#f59cc5}

.bb-variantes{background:#000;color:#fff;font-family:"Chivo",system-ui,sans-serif;border:1px solid #2b2b2b;border-radius:4px;padding:16px 32px;max-width:640px}
.bb-variantes__label{text-transform:uppercase;letter-spacing:.08em;font-size:.75rem;color:#999;font-weight:700;margin:0 0 12px}
.bb-variantes__fila{display:grid;grid-template-columns:1fr auto auto auto;gap:.5em;align-items:center;margin-bottom:.5em}
.bb-variantes__fila input{font-family:inherit;font-size:.9rem;color:#fff;background:#111;border:1px solid #2b2b2b;border-radius:4px;padding:.5em .6em;width:100%;box-sizing:border-box}
.bb-variantes__btn{display:inline-flex;align-items:center;padding:.5em 1em;font:700 .8rem "Chivo",system-ui,sans-serif;border-radius:999px;background:transparent;color:#fff;border:1px solid #2b2b2b;cursor:pointer}
.bb-variantes__btn:hover{border-color:#f59cc5;color:#f59cc5}
.bb-variantes__add{margin-top:4px}

.bb-subida{background:#000;color:#fff;font-family:"Chivo",system-ui,sans-serif;padding:24px;max-width:420px;display:flex;flex-direction:column;gap:10px}
.bb-subida label{display:flex;flex-direction:column;gap:.35em;font-size:.85rem;color:#999}
.bb-subida input[type=file]{font:inherit;color:#bcbcbc;background:#111;border:1px solid #2b2b2b;border-radius:4px;padding:.6em .75em}
.bb-subida__fila{display:flex;align-items:center;gap:.6em}
.bb-subida__btn{padding:.5em 1em;font:700 .8rem "Chivo",system-ui,sans-serif;border-radius:999px;background:transparent;color:#fff;border:1px solid #2b2b2b;cursor:pointer}
.bb-subida__btn:hover{border-color:#f59cc5;color:#f59cc5}
.bb-subida__estado{font-size:.8rem;color:#999}
.bb-subida__thumbs{display:flex;gap:.5em;flex-wrap:wrap}
.bb-subida__thumb{position:relative}
.bb-subida__img{width:56px;height:56px;border-radius:2px;background:#111}
.bb-subida__thumb button{position:absolute;top:-.4em;right:-.4em;width:1.3em;height:1.3em;line-height:1;border-radius:50%;border:none;background:#950f1e;color:#fff;font-size:.75rem;cursor:pointer}
.bb-subida__hint{color:#999;font-size:.8rem;margin:0}

.bb-pedidos{background:#000;padding:16px;font-family:"Chivo",system-ui,sans-serif}
.bb-pedidos table{width:100%;border-collapse:collapse;font-size:.85rem}
.bb-pedidos th,.bb-pedidos td{text-align:left;padding:.5em .6em;border-bottom:1px solid #2b2b2b;color:#bcbcbc}
.bb-pedidos th{color:#999;text-transform:uppercase;font-size:.7rem;letter-spacing:.06em}
.bb-pedidos select{font:inherit;color:#fff;background:#111;border:1px solid #2b2b2b;border-radius:4px;padding:.3em .5em}

.bb-prods{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:32px;background:#000;padding:24px;font-family:"Chivo",system-ui,sans-serif;max-width:520px}
.bb-prods__card{display:flex;flex-direction:column;gap:.5em;background:#1a1a1a;border:1px solid #2b2b2b;border-radius:12px;padding:16px;transition:border-color .2s,transform .2s,box-shadow .2s}
.bb-prods__card:hover{border-color:#f59cc5;transform:translateY(-2px);box-shadow:0 10px 24px -12px rgba(245,156,197,.35)}
.bb-prods__img{width:100%;aspect-ratio:1/1;border-radius:4px;background:#111}
.bb-prods__name{font-size:.95rem;font-weight:700;color:#fff;margin:0}
.bb-prods__slug{font-size:.72rem;color:#999;margin:0}
.bb-prods__price{font-size:1rem;font-weight:700;color:#f59cc5;margin:0}
.bb-prods__status{align-self:flex-start;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:.3em .8em;border-radius:999px;margin:0}
.bb-prods__status.is-active{color:#f59cc5;background:rgba(245,156,197,.12)}
.bb-prods__status.is-inactive{color:#999;background:#111}
.bb-prods__actions{display:flex;flex-direction:column;gap:.4em;margin-top:auto}
.bb-prods__btn{padding:.5em 1em;font:700 .8rem "Chivo",system-ui,sans-serif;border-radius:999px;background:transparent;color:#fff;border:1px solid #2b2b2b;cursor:pointer;width:100%}
.bb-prods__btn:hover{border-color:#f59cc5;color:#f59cc5}

.wp-nav{display:flex;flex-direction:column;gap:1.6rem;width:250px;min-height:560px;box-sizing:border-box;padding:1.8rem 1.4rem 1.4rem;background:#fff;border-right:1px solid rgba(19,35,63,.09);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-nav__brand{font:400 1.35rem/1 "Instrument Serif",Georgia,serif;letter-spacing:.04em}
.wp-nav__brand small{display:block;margin-top:.35rem;font:400 .75rem/1.3 "Archivo",system-ui,sans-serif;color:#56617a}
.wp-nav nav{display:flex;flex-direction:column;gap:1.3rem}
.wp-nav__label{margin:0 0 .25rem .6rem;color:#0a63d8;font:600 .72rem/1.4 "Archivo",system-ui,sans-serif}
.wp-nav__group a{display:block;padding:.42rem .7rem;border-radius:8px;color:#13233f;font:400 .9rem/1.3 "Archivo",system-ui,sans-serif;text-decoration:none}
.wp-nav__group a:hover{background:rgba(0,0,0,.05)}
.wp-nav__group a[aria-current=page]{background:#13233f;color:#fff;font-weight:500}
.wp-nav__user{display:flex;align-items:center;justify-content:space-between;gap:.6rem;margin-top:auto;padding-top:1rem;border-top:1px solid rgba(19,35,63,.09);font-size:.88rem}
.wp-nav__user span{display:flex;flex-direction:column}
.wp-nav__user small{color:#56617a;font-size:.8rem}
.wp-nav__user button{padding:0;border:0;background:none;color:inherit;font:inherit;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.wp-nav__site{color:#56617a;font-size:.8rem;text-decoration:none}
.wp-nav__site:hover{color:#0a63d8}

.wp-top{display:flex;align-items:flex-end;gap:1.2rem;flex-wrap:wrap;padding:2.6rem 2.6rem 1.2rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-top__title{flex:1;min-width:0}
.wp-top__eyebrow{margin:0 0 .3rem;color:#0a63d8;font:600 .85rem/1.4 "Archivo",system-ui,sans-serif}
.wp-top h1{margin:0;font:400 2.7rem/1 "Instrument Serif",Georgia,serif;text-transform:uppercase;letter-spacing:.01em;color:#13233f}
.wp-top h1 em{font:italic 400 1em/1 "Instrument Serif",Georgia,serif;text-transform:none;color:#0a63d8}
.wp-top__sub{margin:.4rem 0 0;color:#56617a;font-size:1rem}
.wp-top__actions{display:flex;flex-wrap:wrap;gap:.5rem}
.wp-top__btn{padding:.62rem 1.2rem;border-radius:980px;background:#13233f;color:#fff;font:500 .9rem/1.2 "Archivo",system-ui,sans-serif;text-decoration:none}
.wp-top__btn:hover{background:#0a63d8}
@media (max-width:700px){.wp-top{padding:1.2rem 1rem}.wp-top h1{font-size:1.9rem}.wp-top__actions{width:100%}}

.wp-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem;padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-stat{display:flex;flex-direction:column;gap:.45rem;padding:1.1rem 1.2rem;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);color:#13233f;text-decoration:none}
a.wp-stat:hover{border-color:#13233f}
.wp-stat__label{color:#56617a;font:500 .82rem/1.4 "Archivo",system-ui,sans-serif}
.wp-stat__value{font:400 2.5rem/1 "Instrument Serif",Georgia,serif;letter-spacing:.01em}
.wp-stat__note{font-size:.8rem;color:#56617a}
.wp-stat--sky{background:#e7f0f6}
.wp-stat--sun{background:#fff6e5}
.wp-stat--blue{background:#13233f;color:#fff}
.wp-stat--blue .wp-stat__label,.wp-stat--blue .wp-stat__note{color:rgba(255,255,255,.8)}
@media (max-width:700px){.wp-stats{grid-template-columns:1fr 1fr}}

.wp-notice{margin:0 0 1rem;padding:.9rem 1.1rem;border-radius:12px;font:400 .93rem/1.5 "Archivo Variable","Archivo",system-ui,sans-serif;max-width:560px}
.wp-notice a{color:inherit;font-weight:600}
.wp-notice--info{background:#d3e3ec;color:#13233f}
.wp-notice--ok{background:#eaf5ee;color:#1b4d33}
.wp-notice--warn{background:#fff4d9;color:#6b4300}
.wp-notice--bad{background:#fbeceb;color:#7a1f1f}

.wp-cal{padding:1.6rem 1.8rem 1.4rem;border:1px solid rgba(19,35,63,.09);border-radius:20px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-cal [data-st]{--bar:#dfe6ee;--ink:#13233f}
.wp-cal [data-st=confirmada]{--bar:#13233f;--ink:#fff}
.wp-cal [data-st=encurso]{--bar:#1f7a4d;--ink:#fff}
.wp-cal [data-st=pendiente]{--bar:#ffcf66;--ink:#4d3200}
.wp-cal [data-st=bloqueo]{--bar:repeating-linear-gradient(-45deg,#c9d3df 0 6px,#dde4ec 6px 12px);--ink:#13233f}
.wp-cal__head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1.4rem}
.wp-cal__head h2{margin:0;font:400 2.4rem/1 "Instrument Serif",Georgia,serif;text-transform:uppercase}
.wp-cal__head p{margin:.45rem 0 0;color:#56617a;font-size:.92rem}
.wp-cal__nav{display:flex;gap:.5rem}
.wp-cal__arrow,.wp-cal__today{display:grid;place-items:center;min-width:42px;height:42px;padding:0 .9rem;border-radius:999px;background:#fff;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18);color:#13233f;text-decoration:none;font-weight:500;box-sizing:border-box}
.wp-cal__arrow{padding:0}
.wp-cal__arrow:hover,.wp-cal__today:hover{background:#13233f;color:#fff;box-shadow:none}
.wp-cal__grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:1px solid rgba(19,35,63,.09);border-left:1px solid rgba(19,35,63,.09);border-radius:14px;overflow:hidden}
.wp-cal__dow{padding:.6rem .7rem;border-right:1px solid rgba(19,35,63,.09);border-bottom:1px solid rgba(19,35,63,.09);background:#f3f6fa;color:#56617a;font-size:.8rem;font-weight:500}
.wp-cal__day{position:relative;min-height:112px;padding:.55rem .65rem;border-right:1px solid rgba(19,35,63,.09);border-bottom:1px solid rgba(19,35,63,.09);background:#fff}
.wp-cal__day--we{background:#fafbfd}
.wp-cal__num{display:inline-grid;place-items:center;min-width:28px;height:28px;border-radius:999px;font:400 1.15rem/1 "Instrument Serif",Georgia,serif}
.wp-cal__day--today .wp-cal__num{background:#0a63d8;color:#fff}
.wp-cal__price{position:absolute;top:.75rem;right:.7rem;color:#56617a;font-size:.8rem;font-variant-numeric:tabular-nums}
.wp-cal__bar{position:absolute;left:-1px;right:-1px;top:46px;height:44px;display:flex;align-items:center;background:var(--bar);color:var(--ink);z-index:1}
.wp-cal__bar--in{left:50%;border-radius:999px 0 0 999px;z-index:2}
.wp-cal__bar--out{right:50%;border-radius:0 999px 999px 0}
.wp-cal__who{display:flex;flex-direction:column;padding:0 .7rem;font-size:.85rem;font-weight:600;line-height:1.2;white-space:nowrap}
.wp-cal__who small{font-weight:400;font-size:.75rem;opacity:.85}
.wp-cal__legend{display:flex;flex-wrap:wrap;gap:.6rem 1.6rem;margin:1.2rem 0 0;padding:0;list-style:none;color:#56617a;font-size:.85rem}
.wp-cal__legend li{display:flex;align-items:center;gap:.5rem}
.wp-cal__legend span{width:22px;height:12px;border-radius:999px;background:var(--bar)}
@media (max-width:800px){.wp-cal{padding:1rem .8rem}.wp-cal__day{min-height:76px;padding:.35rem}.wp-cal__bar{top:34px;height:22px}.wp-cal__who{font-size:.68rem}.wp-cal__who small{display:none}.wp-cal__price{top:auto;bottom:.3rem;right:.3rem;font-size:.66rem}}

.wp-estados{display:flex;flex-wrap:wrap;gap:.5rem;padding:1rem;font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-status{display:inline-flex;align-items:center;padding:.15rem .6rem;border-radius:980px;background:var(--st-bg);color:var(--st-ink);font:500 .78rem/1.4 "Archivo",system-ui,sans-serif;white-space:nowrap}
.wp-status[data-status]{--st-bg:#f3f6fa;--st-ink:#56617a}
.wp-status[data-status=solicitud],.wp-status[data-status=pendiente_pago]{--st-bg:#ffefc7;--st-ink:#8a5700}
.wp-status[data-status=confirmada]{--st-bg:#d3e3ec;--st-ink:#0a63d8}
.wp-status[data-status=en_curso]{--st-bg:#d7ecdf;--st-ink:#1f7a4d}
.wp-status[data-status=cancelada],.wp-status[data-status=rechazada]{--st-bg:#f6e0dc;--st-ink:#c62f2f}

.wp-list{padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-list__toolbar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.8rem;margin-bottom:1rem}
.wp-list__tabs{display:inline-flex;gap:2px;padding:3px;border-radius:10px;background:#e4ebf2}
.wp-list__tabs a{padding:.4rem .95rem;border-radius:8px;color:#13233f;font:500 .85rem/1.3 "Archivo",system-ui,sans-serif;text-decoration:none}
.wp-list__tabs a span{color:#0a63d8;font-weight:600;margin-left:.3rem}
.wp-list__tabs a[aria-current=page]{background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12)}
.wp-list__search{display:flex;gap:.5rem;flex:1 1 300px;max-width:520px}
.wp-list__search input{flex:1;min-width:0;min-height:40px;padding:.5rem .85rem;border:1px solid #d2d2d7;border-radius:10px;font:400 .95rem "Archivo",system-ui,sans-serif}
.wp-list__search input:focus{outline:none;border-color:#0a63d8;box-shadow:0 0 0 4px rgba(0,113,227,.18)}
.wp-list__search button{padding:.42rem 1rem;border:0;border-radius:980px;background:#fff;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18);font:500 .85rem "Archivo",system-ui,sans-serif;color:#13233f;cursor:pointer}
.wp-list__wrap{overflow-x:auto;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12)}
.wp-list table{width:100%;border-collapse:collapse;font-size:.93rem}
.wp-list th,.wp-list td{padding:.85rem .8rem;border-bottom:1px solid rgba(19,35,63,.09);text-align:left;vertical-align:middle;white-space:nowrap}
.wp-list th{color:#56617a;font:500 .82rem/1.4 "Archivo",system-ui,sans-serif}
.wp-list tbody tr{cursor:pointer;transition:background .15s}
.wp-list tbody tr:hover{background:#f5f5f7}
.wp-list td small{display:block;font-size:.78rem;color:#56617a}
.wp-list .num{text-align:right;font-variant-numeric:tabular-nums}
.wp-list__who{display:flex;align-items:center;gap:.7rem;color:inherit;text-decoration:none}
.wp-list__who div{display:flex;flex-direction:column;line-height:1.3}
.wp-list__av{display:inline-grid;place-items:center;flex-shrink:0;width:34px;height:34px;border-radius:50%;background:#e7f0f6;color:#13233f;font:400 1rem/1 "Instrument Serif",Georgia,serif}
.wp-list__st{padding:.15rem .6rem;border-radius:980px;font-size:.78rem;font-weight:500}
.wp-list__st--ok{background:#d3e3ec;color:#0a63d8}.wp-list__st--warn{background:#ffefc7;color:#8a5700}
.wp-list__pag{display:flex;align-items:center;justify-content:space-between;margin-top:1.2rem;font-size:.9rem;color:#56617a}
.wp-list__pag a{padding:.42rem .9rem;border-radius:980px;background:#fff;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18);color:#13233f;text-decoration:none;font-size:.82rem}

.wp-confirm-demo button{padding:.62rem 1.2rem;border:0;border-radius:980px;background:#fdeceb;color:#d70015;font:500 .9rem "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-confirm{width:min(440px,calc(100vw - 2rem));padding:0;border:0;border-radius:20px;background:#fff;color:#13233f;box-shadow:0 40px 80px -30px rgba(19,35,63,.5);font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-confirm::backdrop{background:rgba(19,35,63,.35);backdrop-filter:blur(4px)}
.wp-confirm[open]{animation:wp-confirm-in .18s ease-out}
@keyframes wp-confirm-in{from{opacity:0;transform:translateY(8px) scale(.98)}}
.wp-confirm__box{display:flex;flex-direction:column;gap:.8rem;padding:1.8rem 1.8rem 1.5rem}
.wp-confirm__title{margin:0;font:400 1.7rem/1.1 "Instrument Serif",Georgia,serif;text-transform:uppercase;color:#13233f}
.wp-confirm__text{margin:0;color:#56617a;line-height:1.5}
.wp-confirm__text:empty{display:none}
.wp-confirm__buttons{display:flex;justify-content:flex-end;gap:.6rem;margin-top:.8rem}
.wp-confirm__btn{padding:.7rem 1.3rem;border:0;border-radius:999px;background:#13233f;color:#fff;font:500 .9rem/1.2 "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-confirm__btn:hover{background:#0a63d8}
.wp-confirm__btn--ghost{background:#fff;color:#13233f;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18)}
.wp-confirm__btn--ghost:hover{background:#f3f6fa}
.wp-confirm.is-danger .wp-confirm__btn:not(.wp-confirm__btn--ghost){background:#c62f2f}

.wp-login{display:grid;grid-template-columns:1.1fr 1fr;min-height:520px;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-login__photo{position:relative;overflow:hidden;background:#13233f}
.wp-login__img{position:absolute;inset:0;background:linear-gradient(160deg,#7fb3d5 0%,#d3e3ec 45%,#e9d8b4 70%,#13233f 100%)}
.wp-login__photo p{position:absolute;left:2rem;bottom:1.6rem;margin:0;color:#fff;font:500 .62rem/1.4 "Archivo",system-ui,sans-serif;font-stretch:125%;letter-spacing:.22em;text-transform:uppercase;text-shadow:0 1px 8px rgba(0,0,0,.4)}
.wp-login__side{display:flex;flex-direction:column;justify-content:center;gap:1.8rem;width:100%;max-width:400px;margin:0 auto;padding:3rem 1.5rem;box-sizing:border-box}
.wp-login__logo{font:400 1.4rem/1 "Instrument Serif",Georgia,serif;letter-spacing:.04em}
.wp-login__logo small{display:block;font:400 .75rem "Archivo",sans-serif;color:#56617a;margin-top:.3rem;letter-spacing:0}
.wp-login h1{margin:0;font:400 1.6rem/1 "Instrument Serif",Georgia,serif;text-transform:uppercase}
.wp-login h1 em{font-style:italic;text-transform:none;color:#0a63d8}
.wp-login__error{padding:.9rem 1.1rem;border-radius:12px;background:#fbeceb;color:#7a1f1f;font-size:.93rem}
.wp-login__form{display:flex;flex-direction:column;gap:1.3rem}
.wp-login__form label{display:flex;flex-direction:column;gap:.4rem;color:#56617a;font:500 .82rem/1.5 "Archivo",system-ui,sans-serif}
.wp-login__form input{min-height:44px;padding:.65rem .85rem;border:1px solid #d2d2d7;border-radius:10px;background:#fff;font:400 .95rem "Archivo",system-ui,sans-serif;color:#13233f}
.wp-login__form input:focus{outline:none;border-color:#0a63d8;box-shadow:0 0 0 4px rgba(0,113,227,.18)}
.wp-login__form button{padding:.75rem 1.2rem;border:0;border-radius:980px;background:#13233f;color:#fff;font:500 .95rem "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-login__form button:hover{background:#0a63d8}
@media (max-width:800px){.wp-login{grid-template-columns:1fr}.wp-login__photo{height:30vh}}

.wp-settings{max-width:640px;padding:1.2rem 1.8rem;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-set{display:flex;align-items:center;justify-content:space-between;gap:1.5rem;padding:.95rem 0}
