.wp-set__value{display:inline-flex;flex-shrink:0;align-items:center;gap:.55rem}
.wp-set__value input{width:5.2rem;min-height:40px;padding:.45rem .6rem;text-align:right;font:400 .95rem "Archivo",system-ui,sans-serif;font-variant-numeric:tabular-nums;border:1px solid #d2d2d7;border-radius:10px;color:#13233f;box-sizing:border-box}
