.wp-chat__meta{padding:0 .4rem;color:#56617a;font-size:.75rem}
.wp-chat__form{display:flex;align-items:flex-end;gap:.6rem;padding:.5rem;border:1px solid rgba(19,35,63,.09);border-radius:22px;background:#fff}
.wp-chat__form:focus-within{border-color:#0a63d8}
.wp-chat__form textarea{flex:1;min-height:2.6rem;padding:.55rem .7rem;border:0;background:none;font:inherit;font-size:.95rem;resize:none}
.wp-chat__form textarea:focus{outline:none}
.wp-chat__send{flex-shrink:0;padding:.7rem 1.3rem;border:0;border-radius:999px;background:#13233f;color:#fff;font:500 .9rem "Archivo",system-ui,sans-serif;cursor:pointer}

.wp-email{display:grid;gap:1rem;padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;max-width:720px}
.wp-email__tabs{display:inline-flex;justify-self:start;gap:2px;padding:3px;border-radius:10px;background:#e4ebf2}
.wp-email__tabs a{padding:.4rem .95rem;border-radius:8px;color:#13233f;font:500 .85rem "Archivo",system-ui,sans-serif;text-decoration:none}
.wp-email__tabs a[aria-current=page]{background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12)}
.wp-email__frame{overflow:hidden;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#f6f4ef}
.wp-email__frame--movil{width:100%;max-width:390px;margin-inline:auto;border-radius:28px;border:8px solid #13233f;box-sizing:border-box}
.wp-email__frame iframe{display:block;width:100%;height:320px;border:0}
.wp-email__text{margin:0;padding:1.25rem;overflow-x:auto;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;font:.85rem/1.6 ui-monospace,Menlo,monospace;white-space:pre-wrap}

.wp-btns{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-btn{display:inline-flex;align-items:center;justify-content:center;gap:.55em;padding:.62rem 1.2rem;border:0;border-radius:980px;font:500 .9rem/1.2 "Archivo",system-ui,sans-serif;text-decoration:none;white-space:nowrap;cursor:pointer;transition:background .25s,color .25s,box-shadow .25s}
.wp-btn--primary{background:#13233f;color:#fff}
.wp-btn--primary:hover{background:#0a63d8}
