.wp-btn--ghost:hover{box-shadow:inset 0 0 0 1px #13233f}
.wp-btn--danger{background:#fdeceb;color:#d70015}
.wp-btn--danger:hover{background:#d70015;color:#fff}
.wp-btn--sm{padding:.42rem .9rem;font-size:.82rem}
.wp-btn--link{padding:0 0 .2em;border-radius:0;border-bottom:1px solid currentColor;background:none;color:#13233f}
.wp-btn:disabled{opacity:.5;cursor:not-allowed}

.wp-hoy{max-width:560px;padding:1.6rem 1.8rem;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-hoy__eyebrow{margin:0;color:#0a63d8;font:600 .8rem "Archivo",sans-serif}
.wp-hoy h2{margin:0 0 1.2rem;padding-bottom:.9rem;border-bottom:1px solid rgba(19,35,63,.09);font:400 1.6rem/1.05 "Instrument Serif",Georgia,serif;text-transform:uppercase}
.wp-hoy__todo{display:flex;flex-direction:column;gap:.5rem;margin:0 0 1.2rem;padding:0;list-style:none}
.wp-hoy__todo li{padding:.75rem 1rem;border-left:3px solid;border-radius:0 6px 6px 0;font-size:.93rem}
.wp-hoy__todo a{color:inherit;font-weight:600}
.wp-hoy__bad{color:#7a1f1f;background:#fbeceb;border-color:#c62f2f}
.wp-hoy__warn{color:#6b4300;background:#fff4d9;border-color:#ffb400}
.wp-hoy__info{color:#13233f;background:#d3e3ec;border-color:#0a63d8}
.wp-hoy__week{margin:0;padding:0;list-style:none}
.wp-hoy__week a{display:grid;grid-template-columns:4rem 1fr auto;align-items:center;gap:.9rem;padding:.75rem 0;border-bottom:1px solid rgba(19,35,63,.09);color:inherit;text-decoration:none}
.wp-hoy__week li:last-child a{border-bottom:0}
.wp-hoy__week a:hover .wp-hoy__who{color:#0a63d8}
.wp-hoy__day{display:flex;flex-direction:column;align-items:center;font-size:.75rem;color:#56617a}
.wp-hoy__day strong{font:400 1.6rem/1 "Instrument Serif",Georgia,serif;color:#13233f}
.wp-hoy__who small{display:block;font-size:.8rem;color:#56617a}
.wp-hoy__st{padding:.15rem .6rem;border-radius:980px;background:#d3e3ec;color:#0a63d8;font-size:.78rem;font-weight:500}

.sm-shell{display:grid;grid-template-columns:220px 1fr;min-height:360px;font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;-webkit-font-smoothing:antialiased}
.sm-shell__side{background:#020203;color:#fff;padding:16px 10px;display:flex;flex-direction:column;gap:2px;color-scheme:dark}
.sm-shell__logo{font:400 15px/1.6 "Krona One","Manrope",Arial,sans-serif;letter-spacing:-.02em;padding:6px 10px 16px}
.sm-shell__side a{padding:7px 10px;border-radius:8px;color:#a9a9a9;font-size:13px;font-weight:500;text-decoration:none}
.sm-shell__side a:hover{background:#141416;color:#fff}
