.sm-shell__card p{margin:0 0 16px;color:#55555a;font-size:14px}
.sm-shell__card button{padding:6px 15px;border:0;border-radius:999px;background:#fff;box-shadow:0 0 0 1px rgba(2,2,3,.16);font:500 13px Manrope,system-ui,sans-serif;cursor:pointer}

.sm-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:24px;background:#fff;font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif}
