.ro-menu a span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ro-menu a:hover{background:#fff}.ro-menu a:hover svg{color:#f59a89}
.ro-menu a.on{background:#fff;color:#000;box-shadow:0 2px 10px rgba(20,40,35,.07)}.ro-menu a.on svg{color:#f59a89}
