.ro-movil__btn{display:flex;align-items:center;gap:10px;width:calc(100% - 32px);margin:14px 16px 0;padding:12px 16px;background:#fff;border:1px solid #d6e3df;border-radius:14px;font:inherit;font-weight:600;font-size:15px;color:#000;cursor:pointer;text-align:left;-webkit-tap-highlight-color:transparent}
