.ro-movil__menu{display:none;flex-direction:column;gap:2px;margin:8px 16px 0;padding:12px;background:#fff;border-radius:16px;box-shadow:0 8px 24px rgba(20,40,35,.1)}
.ro-movil__menu.abierto{display:flex}
.ro-movil__menu p{margin:12px 0 4px 12px;font-size:11px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:#8aa39b}
.ro-movil__menu a{display:flex;justify-content:space-between;padding:10px 12px;border-radius:12px;text-decoration:none;font-size:14.5px;font-weight:600;color:#2e4a42}
.ro-movil__menu a.on{background:#f1f7f5}
.ro-movil__menu a b{padding:2px 8px;border-radius:999px;background:#ffb5a7;color:#fff;font-size:12px}

.ro-tabla{background:#fff;border-radius:20px;overflow:auto;box-shadow:0 2px 10px rgba(20,40,35,.05);padding:6px 10px;font-family:'DM Sans',system-ui,-apple-system,'Segoe UI',sans-serif;color:#000}
.ro-tabla table{border-collapse:separate;border-spacing:0;width:100%;font-size:14.5px}
.ro-tabla th,.ro-tabla td{padding:14px;text-align:left;vertical-align:middle}
.ro-tabla th{font-size:12px;font-weight:600;letter-spacing:.03em;color:#8a9b96;background:#fff;position:sticky;top:0;border-bottom:1px solid #eef4f2;white-space:nowrap}
.ro-tabla tbody td{border-bottom:1px solid #f3f7f6}.ro-tabla tbody tr:last-child td{border-bottom:0}
.ro-tabla tbody tr{transition:background .15s}.ro-tabla tbody tr:hover{background:#f6fbf9}
