.ar-barra__ind{position:absolute;top:4px;bottom:4px;left:0;border-radius:999px;background:#d4ec3a;box-shadow:0 2px 10px -2px rgba(212,236,58,.6);transition:transform .35s cubic-bezier(.3,.9,.3,1),width .35s cubic-bezier(.3,.9,.3,1)}
.ar-barra__salir{flex:none;font:inherit;font-size:13px;font-weight:600;cursor:pointer;color:rgba(244,243,238,.75);background:none;border:1px solid rgba(244,243,238,.18);border-radius:999px;padding:8px 14px}
