.ar-tabs{position:relative;display:flex;gap:4px;background:#fff;border:1px solid #e6e4dd;border-radius:14px;padding:6px;overflow-x:auto;font-family:Inter,system-ui,-apple-system,sans-serif;font-size:14px;color:#111;max-width:720px}
.ar-tab{position:relative;z-index:1;flex:1;min-width:112px;text-align:left;border:0;background:none;padding:10px 12px;border-radius:10px;cursor:pointer;font:inherit;color:inherit;transition:color .3s}
.ar-tab b{display:block;font-weight:600;white-space:nowrap}.ar-tab small{color:#6b6b66}
