.ar-match-list{background:#fff;border:1px solid #e6e4dd;border-radius:14px;overflow:hidden;font-family:Inter,system-ui,-apple-system,sans-serif;font-size:14px;color:#111;max-width:760px}
.ar-match{display:grid;grid-template-columns:60px 1fr auto;gap:12px;align-items:center;padding:14px 18px;border-bottom:1px solid #e6e4dd;transition:background .2s}
.ar-match:hover{background:rgba(239,238,233,.55)}
.ar-match__time{font-weight:700;font-size:15px}
.ar-match.full .ar-match__time::after{content:'✓';display:inline-grid;place-items:center;width:16px;height:16px;margin-left:6px;border-radius:50%;background:#d4ec3a;color:#1d2400;font-size:10px;vertical-align:2px}
.ar-match__teams{font-weight:700;font-size:13px}.ar-match__teams span{color:#6b6b66;font-weight:400;margin:0 4px}
.ar-match__meta{color:#6b6b66;font-size:12.5px;margin-top:3px}
.ar-slots{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.ar-slot{border:1.5px dashed rgba(107,107,102,.45);border-radius:999px;padding:6px 12px;background:none;cursor:pointer;white-space:nowrap;font:500 14px Inter,system-ui,sans-serif;color:#6b6b66;display:inline-flex;align-items:center;gap:6px;transition:background .15s,border-color .15s,color .15s,transform .15s,box-shadow .15s}
.ar-slot:hover{border-color:#111;color:#111}
.ar-slot.filled{border-style:solid;border-color:#e6e4dd;background:#efeee9;color:#111;padding-left:4px;cursor:grab}
.ar-slot.warn{border-color:#a3352b;color:#a3352b}
.ar-slot .x{opacity:0;width:0;overflow:hidden;transition:opacity .15s,width .15s;color:#6b6b66}
.ar-slot.filled:hover .x{opacity:1;width:12px}
.ar-slot.drop{border-style:solid;border-color:#9fb81a;background:rgba(212,236,58,.35);color:#111;transform:scale(1.06);box-shadow:0 4px 14px rgba(0,0,0,.12)}
.ar-slot.drop::after{content:'Soltar aquí';margin-left:4px;font-size:11px;font-weight:800;color:#1d2400}
.ar-av{width:22px;height:22px;border-radius:50%;display:inline-grid;place-items:center;font-size:10px;font-weight:700;color:#fff;flex:none}
@media (max-width:600px){.ar-match{grid-template-columns:50px 1fr}.ar-slots{grid-column:1/-1;justify-content:flex-start}}

.ar-modal-fondo{position:relative;min-height:340px;background:rgba(17,17,17,.45);backdrop-filter:blur(3px);display:grid;place-items:center;padding:16px;opacity:0;transition:opacity .18s;font-family:Inter,system-ui,-apple-system,sans-serif;font-size:14px}
