.ar-semana__der{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ar-semana__prog{min-width:130px;margin-right:6px;font-size:13px}.ar-semana__prog span{color:#6b6b66}.ar-semana__prog b{font-size:15px}
.ar-semana__bar{height:4px;background:#e6e4dd;border-radius:4px;margin-top:8px;overflow:hidden}.ar-semana__bar i{display:block;height:100%;background:#d4ec3a}
.ar-semana__btn{display:inline-flex;align-items:center;gap:6px;border:1px solid #e6e4dd;background:#fff;border-radius:999px;padding:8px 12px;font:600 14px Inter,system-ui,sans-serif;cursor:pointer}
