.fi-tabs{position:relative;display:inline-flex;gap:2px;padding:3px;background:#ece9de;border-radius:9999px;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif}
.fi-tab{position:relative;z-index:1;padding:.5rem 1.15rem;border-radius:9999px;font-size:.85rem;font-weight:600;cursor:pointer;border:none;background:transparent;color:#3a3a33;font-family:inherit;transition:background .25s cubic-bezier(.16,1,.3,1),color .25s,box-shadow .25s}
.fi-tab.active{background:#fff;color:#15161a;box-shadow:0 1px 2px rgba(21,22,26,.04)}
.fi-tabs__pastilla{position:absolute;top:0;left:0;z-index:0;border-radius:9999px;background:#fff;box-shadow:0 1px 2px rgba(21,22,26,.04),0 1px 3px rgba(21,22,26,.08);pointer-events:none;transition:none}
.fi-tabs--lista .fi-tabs__pastilla{transition:transform .34s cubic-bezier(.16,1,.3,1),width .34s cubic-bezier(.16,1,.3,1),height .34s cubic-bezier(.16,1,.3,1)}
.fi-tabs--con-pastilla .fi-tab.active{background:transparent;box-shadow:none}
.fi-tab__badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:9999px;background:#a3352b;color:#fff;font-size:.68rem;font-weight:700;margin-left:.3rem;box-sizing:border-box}

.fi-toasts{display:flex;flex-direction:column;gap:.6rem;max-width:min(360px,calc(100vw - 2rem));padding:1rem;background:#f7f6f0;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif;color:#15161a}
.fi-toast{display:flex;align-items:flex-start;gap:.6rem;background:#fff;border:1px solid rgba(21,22,26,.07);border-radius:16px;padding:.85rem 1rem;box-shadow:0 24px 60px -16px rgba(21,22,26,.18),0 4px 12px rgba(21,22,26,.05);font-size:.86rem;animation:fi-toast-in .3s cubic-bezier(.16,1,.3,1)}
.fi-toast.leaving{animation:fi-toast-out .25s cubic-bezier(.16,1,.3,1) forwards}
.fi-toast__dot{width:8px;height:8px;border-radius:50%;margin-top:.35rem;flex-shrink:0}
.fi-toast--ok .fi-toast__dot{background:#2f6b2f}.fi-toast--err .fi-toast__dot{background:#a3352b}.fi-toast--info .fi-toast__dot{background:#aebb0c}
.fi-toast__texto{flex:1;min-width:0}
.fi-toast__acc{border:0;background:none;padding:0;font:inherit;font-weight:700;text-decoration:underline;cursor:pointer;color:#15161a}
.fi-toast__x{flex-shrink:0;background:transparent;border:none;cursor:pointer;color:#3a3a33;font-size:1.15rem;line-height:1;padding:.15rem .35rem;margin:-.15rem -.25rem 0 0;border-radius:8px;font-family:inherit}
