.fi-mes button{font:inherit;color:#15161a;cursor:pointer}
.fi-mes__paso{flex:0 0 40px;display:grid;place-items:center;border:none;background:transparent;border-radius:11px;font-size:1.2rem!important}
.fi-mes__paso:hover:not(:disabled){background:rgba(21,22,26,.06)}
.fi-mes button:disabled{opacity:.3;cursor:default}
.fi-mes__boton{flex:1;display:flex;align-items:center;justify-content:center;gap:.5rem;border:none;border-left:1px solid rgba(21,22,26,.07);border-right:1px solid rgba(21,22,26,.07);background:transparent;font-size:.95rem;font-weight:600}
.fi-mes__boton .ic{font-size:.8rem;opacity:.55}
.fi-mes__panel{margin-top:8px;width:280px;padding:.75rem;background:#fff;border:1px solid rgba(21,22,26,.08);border-radius:16px;box-shadow:0 24px 60px -16px rgba(21,22,26,.18),0 4px 12px rgba(21,22,26,.05);box-sizing:border-box}
