.fi-pin{max-width:340px;padding:2rem 1rem;text-align:center;background:#f7f6f0;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif;color:#15161a}
.fi-pin__tit{margin:0;font-weight:700;font-size:1.2rem}
.fi-pin__dots{display:flex;justify-content:center;gap:1rem;margin:1.75rem 0}
.fi-pin__dots span{width:1rem;height:1rem;border-radius:50%;border:2px solid rgba(21,22,26,.2);transition:background .15s,border-color .15s,transform .15s}
.fi-pin__dots span.filled{background:#15161a;border-color:#15161a;transform:scale(1.1)}
.fi-pin__dots.shake{animation:fi-shake .4s}
@keyframes fi-shake{0%,100%{transform:translateX(0)}20%{transform:translateX(-10px)}40%{transform:translateX(10px)}60%{transform:translateX(-8px)}80%{transform:translateX(8px)}}
.fi-pin__teclado{display:grid;grid-template-columns:repeat(3,1fr);gap:.85rem;max-width:300px;margin:0 auto}
